/**
 * Macros: named G-code snippets the operator runs with one click (docs/API_REFERENCE.md §7.6).
 *
 * Pure and dependency-free: the record type, the limits and the validation rules, used by the
 * backend (src/server/macros.ts, authoritative: it validates on save and again before a run) and by
 * the UI (src/lib/macros/library.ts, src/components/macros/), which checks the same rules before it
 * sends so the operator sees the reason at once.
 */

export interface Macro {
  /** 16 hex characters, generated by the server. */
  id: string;
  name: string;
  /** G-code lines separated by `\n` (normalised by the server). */
  content: string;
  /** Last save, epoch ms (server clock). */
  mtime: number;
}

export const MACRO_NAME_MAX = 60;
/** Characters of content (plain ASCII, so also bytes). */
export const MACRO_CONTENT_MAX = 10_000;
export const MACROS_MAX = 50;

export const MACRO_ID_PATTERN = /^[a-f0-9]{16}$/;

export type MacroInputResult = { ok: true; name: string; content: string } | { ok: false; error: string };

/** `\r\n` / `\r` → `\n`, trailing blank lines and trailing spaces removed. */
export function normalizeMacroContent(content: string): string {
  return content
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => line.replace(/[ \t]+$/, ''))
    .join('\n')
    .replace(/\n+$/, '');
}

/** The lines the Feeder will get: non-blank lines, in order (as the `gcode` command splits them). */
export function macroLines(content: string): string[] {
  return content.split(/\r?\n/).filter((line) => line.trim().length > 0);
}

/** A line without its `( … )` and `; …` comments, for the word checks below. */
function codeOf(line: string): string {
  return line.replace(/\([^)]*\)/g, ' ').replace(/;.*$/, '');
}

/**
 * Checks a macro's name and content. Rules:
 *  - name: 1–60 characters after trimming, no control characters;
 *  - content: at least one non-blank line, at most 10,000 characters, plain printable ASCII plus
 *    tab and newline. Anything else would reach the serial port as UTF-8 bytes 0x80–0xFF, which
 *    GRBL/FluidNC read as real-time commands (0x85 jog cancel, 0x9x overrides, 0xA0 coolant…);
 *  - no `%wait` (in a manual line it holds the job Sender, not the Feeder: CNCjs quirk, see
 *    filters.ts) and no M0 / M1 / M6 (they hold the Feeder, and nothing but Reset releases it).
 */
export function validateMacroInput(name: unknown, content: unknown): MacroInputResult {
  if (typeof name !== 'string') return { ok: false, error: 'The name is required' };
  const trimmed = name.trim();
  if (!trimmed) return { ok: false, error: 'The name is required' };
  if (trimmed.length > MACRO_NAME_MAX) return { ok: false, error: `The name is longer than ${MACRO_NAME_MAX} characters` };
  if (/[\u0000-\u001f\u007f-\u009f]/.test(trimmed)) return { ok: false, error: 'The name contains control characters' };

  if (typeof content !== 'string') return { ok: false, error: 'The G-code is required' };
  const text = normalizeMacroContent(content);
  if (macroLines(text).length === 0) return { ok: false, error: 'The macro has no G-code lines' };
  if (text.length > MACRO_CONTENT_MAX) {
    return { ok: false, error: `The G-code is longer than ${MACRO_CONTENT_MAX.toLocaleString('en-US')} characters` };
  }
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const bad = /[^\t\x20-\x7e]/.exec(line);
    if (bad) {
      const code = bad[0].charCodeAt(0);
      const what = code < 0x20 || code === 0x7f ? 'a control character' : `“${bad[0]}”, which is not plain ASCII`;
      return { ok: false, error: `Line ${i + 1} contains ${what}. Only plain ASCII text can be sent to the controller.` };
    }
    if (/^\s*%\s*wait\b/i.test(line)) {
      return { ok: false, error: `Line ${i + 1}: %wait is not supported in macros. Use G4 P<seconds> for a dwell.` };
    }
    // `%msg …` / `%var=…` lines never reach the controller, so only G-code lines are checked.
    const pause = /^\s*%/.test(line) ? null : /(?:^|[^A-Za-z0-9.])M0*([016])(?![0-9.])/i.exec(codeOf(line));
    if (pause) {
      return {
        ok: false,
        error: `Line ${i + 1}: M${pause[1]} is not supported in macros. It would hold the command queue until Reset.`,
      };
    }
  }
  return { ok: true, name: trimmed, content: text };
}

/** A stored macro as read back from the rc file (hand edits included); null if malformed. */
export function asMacro(value: unknown): Macro | null {
  if (!value || typeof value !== 'object') return null;
  const m = value as Record<string, unknown>;
  if (typeof m.id !== 'string' || !MACRO_ID_PATTERN.test(m.id)) return null;
  if (typeof m.name !== 'string' || typeof m.content !== 'string') return null;
  const mtime = typeof m.mtime === 'number' && Number.isFinite(m.mtime) ? m.mtime : 0;
  return { id: m.id, name: m.name, content: m.content, mtime };
}
